        sb = ''
        i = 0

        # Handle number initialization
        if s[i] != '[':
            while i < len(s) and (s[i].isdigit() or s[i] == '-'):
                sb += s[i]
                i += 1
            num = int(sb)
            return NestedInteger(num)

        # Main deserialization logic
        while i < len(s):
            if s[i] == '[':
                ni = NestedInteger()
                if workStack:
                    lastNi = workStack.pop()
                    lastNi.add(ni)
                    workStack.append(lastNi)
                workStack.append(ni)
                i += 1
            elif s[i] == ',':
                i += 1
            elif s[i] == ']':
                completedNi = workStack.pop()
                result = completedNi
                i += 1
            else:
                sb = ''
                while i < len(s) and (s[i].isdigit() or s[i] == '-'):
                    sb += s[i]
                    i += 1
                num = int(sb)
                if workStack:
                    ni = workStack.pop()
                else:
                    ni = NestedInteger()
